(()=>{
'use strict';const $=s=>document.querySelector(s),core=window.UnitCircleLesson,num=window.LinearLesson;
function math(host,tex){const e=document.createElement('span');e.dataset.tex=tex;host.replaceChildren(e);}
function decimal(n,digits=4){return n.toFixed(digits).replace('.','{,}');}
function piTex(deg){const q=num.rational(deg,180);if(q.n===0)return '0';const top=Math.abs(q.n)===1?'\\pi':Math.abs(q.n)+'\\pi';return(q.n<0?'-':'')+(q.d===1?top:`\\frac{${top}}{${q.d}}`);}
function draw(){const deg=Number($('#unit-angle').value),c=window.TangentLesson.ratios(deg),p=core.point(c.cos,c.sin),x=p.x,y=p.y;$('#unit-angle-output').value=deg+'°';$('#cos-component').setAttribute('x2',x);for(const [key,value] of Object.entries({x1:x,x2:x,y1:180,y2:y}))$('#sin-component').setAttribute(key,value);$('#unit-ray').setAttribute('x2',x);$('#unit-ray').setAttribute('y2',y);$('#unit-point').setAttribute('cx',x);$('#unit-point').setAttribute('cy',y);const sx=Math.sign(c.cos),sy=Math.sign(c.sin);$('#right-angle').setAttribute('d',sx&&sy?`M${x-sx*10} 180L${x-sx*10} ${180-sy*10}L${x} ${180-sy*10}`:'');$('#unit-angle-arc').setAttribute('d',core.arc(deg).map((q,i)=>`${i===0?'M':'L'}${q.x} ${q.y}`).join(' '));math($('#unit-angle-equation'),`\\theta=${deg}^\\circ=${piTex(deg)}\\text{ rad}`);math($('#cos-value'),`\\cos\\theta${c.cosTex===null?'\\approx':'='}${c.cosTex===null?decimal(c.cos):c.cosTex}`);math($('#sin-value'),`\\sin\\theta${c.sinTex===null?'\\approx':'='}${c.sinTex===null?decimal(c.sin):c.sinTex}`);math($('#unit-pair'),`P=(\\cos\\theta,\\sin\\theta)\\approx(${decimal(c.cos)},${decimal(c.sin)})`);for(const key of ['tan','cot','sec','csc']){if(c[key]===null)$('#'+key+'-value').textContent='Tidak terdefinisi';else math($('#'+key+'-value'),'\\'+key+'\\theta\\approx'+decimal(c[key]));}const place=c.cos===0||c.sin===0?'Titik berada pada sumbu, bukan di dalam suatu kuadran.':`Titik berada di kuadran ${c.cos>0?(c.sin>0?'I':'IV'):(c.sin>0?'II':'III')}.`;$('#unit-feedback').textContent=(c.cos===0?'Kosinus nol: tangen dan sekan tidak terdefinisi. ':c.sin===0?'Sinus nol: kotangen dan kosekan tidak terdefinisi. ':'Semua pembagi bukan nol. ')+place+' '+(c.cosTex===null?'Nilai sudut ini ditampilkan sebagai pendekatan empat angka desimal.':'Kartu sinus dan kosinus menampilkan nilai tepat; rasio lain dan pasangan koordinat ditampilkan sebagai pendekatan empat angka desimal.')+' Koordinat bertanda menunjukkan arah. Panjang sisi segitiga, bila dipakai, adalah besar koordinat tanpa tanda.';$('#unit-plot').setAttribute('aria-label',`Lingkaran satuan pada sudut ${deg} derajat. Koordinat mendatar atau kosinus sekitar ${c.cos.toFixed(4)}; koordinat tegak atau sinus sekitar ${c.sin.toFixed(4)}. ${place}`);}
$('#unit-angle').addEventListener('input',draw);document.querySelectorAll('[data-angle]').forEach(button=>button.addEventListener('click',()=>{$('#unit-angle').value=button.dataset.angle;draw();}));$('#reset-unit').addEventListener('click',()=>{$('#unit-angle').value=45;draw();});draw();
const questions=[{tex:String.raw`\tan45^\circ`,prompt:'Berapa nilainya?',n:1,d:1,hint:'Sinus dan kosinus sudut empat puluh lima derajat sama besar.',why:'Membagi dua nilai sama yang bukan nol menghasilkan satu.'},{tex:String.raw`\cos\theta=4/5,\quad\sin\theta=3/5`,prompt:'Berapa tangen sudut tersebut?',n:3,d:4,hint:'Bagi sinus dengan kosinus.',why:'Tiga per lima dibagi empat per lima menghasilkan tiga per empat.'},{tex:String.raw`\sin\theta=3/5`,prompt:'Berapa kosekan sudut tersebut?',n:5,d:3,hint:'Kosekan adalah kebalikan nilai sinus.',why:'Kebalikan tiga per lima adalah lima per tiga.'}];const solved=new Set();function report(i,ok,text){const e=$('#feedback'+i);e.className='feedback '+(ok?'correct':'incorrect');e.textContent=text;if(ok)solved.add(i);$('#progress').textContent=`${solved.size} dari 6 latihan sudah dijawab tepat.`;}
$('#questions').innerHTML=questions.map((q,i)=>`<div class="question"><h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><p>${q.prompt}</p><form data-question="${i}"><label for="answer${i}">Jawabanmu</label><div class="answer-line"><input id="answer${i}" type="text" required autocomplete="off" aria-describedby="feedback${i}"><button class="button" type="submit">Periksa jawaban</button></div></form><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Butuh petunjuk?</summary><p>${q.hint}</p></details><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details></div>`).join('');document.querySelectorAll('form[data-question]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const i=Number(form.dataset.question),q=questions[i],a=num.parseAnswer($('#answer'+i).value),ok=num.equalAnswer(a,num.rational(q.n,q.d));report(i,ok,ok?'Tepat. '+q.why:!a?'Tulis satu bilangan, misalnya 3/4 atau 1.':'Belum tepat. Periksa definisi rasio dan pembaginya.');}));
const choices=[{tex:String.raw`\tan90^\circ`,prompt:'Manakah pernyataan yang benar?',options:[{text:'Nilainya nol.'},{text:'Tidak terdefinisi karena kosinus nol.'},{text:'Nilainya tak hingga.'}],answer:1,why:'Definisi tangen membagi sinus dengan kosinus. Pada sudut ini pembaginya nol.'},{tex:String.raw`\cot90^\circ`,prompt:'Berapa nilainya?',options:[{text:'Nol.'},{text:'Satu.'},{text:'Tidak terdefinisi.'}],answer:0,why:'Kotangen adalah kosinus dibagi sinus. Nol dibagi satu menghasilkan nol.'},{tex:String.raw`\theta=135^\circ`,prompt:'Bagaimana tanda tangen dan sekan?',options:[{text:'Keduanya positif.'},{text:'Tangen negatif, sekan positif.'},{text:'Keduanya negatif.'}],answer:2,why:'Di kuadran II, sinus positif dan kosinus negatif. Tangen dan kebalikan kosinus sama-sama negatif.'}];for(let j=0;j<choices.length;j++){const i=j+3,q=choices[j],box=document.createElement('div');box.className='question';box.innerHTML=`<h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><fieldset><legend>${q.prompt}</legend>${q.options.map((o,k)=>`<label class="choice"><input type="radio" name="choice${i}" value="${k}" ${o.label?'aria-label="'+o.label+'"':''}>${o.tex?'<span data-tex="'+o.tex+'"></span>':o.text}</label>`).join('')}</fieldset><button type="button" class="button" data-check="${i}">Periksa jawaban</button><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details>`;$('#questions').append(box);box.querySelector('button').addEventListener('click',()=>{const a=$(`[name="choice${i}"]:checked`),ok=!!a&&Number(a.value)===q.answer;report(i,ok,!a?'Pilih jawaban dahulu.':(ok?'Tepat. ':'Belum tepat. ')+q.why);});}
const storage={get(k){try{return localStorage.getItem('fondasi-tangent-'+k)}catch{return null}},set(k,v){try{localStorage.setItem('fondasi-tangent-'+k,v);return true}catch{return false}}};$('#reflection').value=storage.get('reflection')||'';$('#reflection').addEventListener('input',()=>{$('#save-note').textContent=storage.set('reflection',$('#reflection').value)?'Catatan tersimpan di peramban ini.':'Catatan belum dapat disimpan; salin jika diperlukan.';});function complete(saved){$('#complete').textContent='Bacaan sudah ditandai selesai ✓';$('#complete-note').textContent=saved?'Kemajuan tersimpan di peramban ini. Kamu bisa mencoba kembali kapan saja.':'Bacaan selesai; kemajuan belum dapat disimpan di peramban ini.';}$('#complete').addEventListener('click',()=>complete(storage.set('complete','yes')));if(storage.get('complete')==='yes')complete(true);
})();